use super::prelude::*;

/// v0.111.0 Models.Potions/PotionOfBinding.cs applies Weak(1) to the
/// full target group, then Vulnerable(1) to the full group. Each application
/// independently observes Artifact and the power application hooks.
pub(crate) fn drink_potion_of_binding(
    state: &mut CombatState,
    _target: Option<u8>,
) -> EffectResult {
    let targets: smallvec::SmallVec<[sts2_core::CreatureUid; 8]> = state
        .enemy_uids
        .iter()
        .copied()
        .filter(|uid| {
            state
                .creatures
                .iter()
                .any(|c| c.id == uid.0 && c.current_hp > 0)
        })
        .collect();
    for &t in &targets {
        apply_power_to_creature(state, t, PowerKind::Weak, 1);
    }
    for t in targets {
        apply_power_to_creature(state, t, PowerKind::Vulnerable, 1);
    }
    EffectResult::Resolved
}
